    "path": "app/src/main/AndroidManifest.xml",
    "content": "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\">\n\n    <!-- Izin Jaringan untuk Supabase Auth, PostgREST, RPC, dan Realtime -->\n    <uses-permission android:name=\"android.permission.INTERNET\" />\n    <uses-permission android:name=\"android.permission.ACCESS_NETWORK_STATE\" />\n\n    <!-- Izin Bluetooth untuk Android 11 (API 30) ke bawah -->\n    <uses-permission\n        android:name=\"android.permission.BLUETOOTH\"\n        android:maxSdkVersion=\"30\" />\n    <uses-permission\n        android:name=\"android.permission.BLUETOOTH_ADMIN\"\n        android:maxSdkVersion=\"30\" />\n\n    <!-- Izin Bluetooth Runtime untuk Android 12+ (API 31+) untuk Dual Printer ESC/POS -->\n    <uses-permission\n        android:name=\"android.permission.BLUETOOTH_SCAN\"\n        android:usesPermissionFlags=\"neverForLocation\" />\n    <uses-permission android:name=\"android.permission.BLUETOOTH_CONNECT\" />\n\n    <uses-feature\n        android:name=\"android.hardware.bluetooth\"\n        android:required=\"false\" />\n\n    <application\n        android:allowBackup=\"false\"\n        android:label=\"Kereta Malam Cafe\"\n        android:supportsRtl=\"true\"\n        android:theme=\"@android:style/Theme.Material.Light.NoActionBar\">\n        <activity\n            android:name=\".MainActivity\"\n            android:configChanges=\"orientation|screenSize|screenLayout|keyboardHidden\"\n            android:exported=\"true\"\n            android:windowSoftInputMode=\"adjustResize\">\n            <intent-filter>\n                <action android:name=\"android.intent.action.MAIN\" />\n                <category android:name=\"android.intent.category.LAUNCHER\" />\n            </intent-filter>\n        </activity>\n    </application>\n\n</manifest>\n"
